-- CINEVA: Add a stable numeric public ID for clean movie URLs.
-- Keep movies.id (UUID) unchanged for existing foreign keys and internal relations.
-- PostgreSQL assigns public_id automatically to existing rows and future inserts.

ALTER TABLE public.movies
ADD COLUMN IF NOT EXISTS public_id BIGINT GENERATED BY DEFAULT AS IDENTITY;

CREATE UNIQUE INDEX IF NOT EXISTS movies_public_id_uidx
ON public.movies (public_id);

COMMENT ON COLUMN public.movies.public_id IS
'Automatically generated numeric public identifier used in public movie URLs.';
